import express, { Application, Request, Response } from "express";
import config from "./app/config/env";
import cors from "cors";
import cookieParser from "cookie-parser";
import { globalErrorHandler } from "./app/middleware/globalErrorHandler";
import { notFound } from "./app/middleware/notFound";
import { authRouter } from "./app/module/auth/auth.route";
import "./app/lib/passport";
import passport from "passport";
import { regionRouter } from "./app/module/region/region.route";
import { managerRouter } from "./app/module/manager/manager.route";
import { categoryRotuer } from "./app/module/category/category.route";
import { serviceRouter } from "./app/module/service/service.route";
import { skillRoute } from "./app/module/skill/skill.route";
import { technicianRoutes } from "./app/module/technician/technician.route";
import { workOrderRouter } from "./app/module/workOrder/workOrder.route";
import { getBkashIdToken } from "./app/lib/bkash";
import { sendResponse } from "./app/utils/sendResponse";
import { paymentRouter } from "./app/module/payment/payment.route";
import { attachmentRouter } from "./app/module/attachment/attachment.route";
import { reportRouter } from "./app/module/report/report.route";
import { feedbackRouter } from "./app/module/feedback/feedback.route";
import { userRouter } from "./app/module/user/user.route";

const app: Application = express();

app.use(
	cors({
		origin: config.frontend_url,
		credentials: true,
	}),
);

app.use(express.urlencoded({ extended: true }));

app.use(express.json());
app.use(cookieParser());

app.use(passport.initialize());

app.get("/", async (req: Request, res: Response) => {
	res.status(200).json({
		success: true,
		message: "Welcome to Field Service Management System",
		author: "Md. Shahdat Hossain",
	});
});

app.get("/bkash-test", async (req: Request, res: Response) => {
	const result = await getBkashIdToken();
	res.status(200).json({
		message: true,
		data: result,
	});
});

app.use("/api/v1/auth", authRouter);
app.use("/api/v1/region", regionRouter);
app.use("/api/v1/manager", managerRouter);
app.use("/api/v1/category", categoryRotuer);
app.use("/api/v1/service", serviceRouter);
app.use("/api/v1/skill", skillRoute);
app.use("/api/v1/technician", technicianRoutes);
app.use("/api/v1/workorder", workOrderRouter);
app.use("/api/v1/payment", paymentRouter);
app.use("/api/v1/attachment", attachmentRouter);
app.use("/api/v1/service-report", reportRouter);
app.use("/api/v1/feedback", feedbackRouter);
app.use("/api/v1/user", userRouter);

app.use(globalErrorHandler);
app.use(notFound);

export default app;
